const pages = $input.all().map(item => item.json);
if (!pages.length) return [{ json: { no_responses: true } }];
const finalPage = pages[pages.length - 1];
if (finalPage.nextPageToken) throw new Error('Google Forms response page cap reached; cursor was not advanced. Increase the bounded page cap or reconcile backlog.');
const responses = pages.flatMap(page => Array.isArray(page.responses) ? page.responses : []);
if (!responses.length) return [{ json: { no_responses: true } }];
const form = $('Read Form question schema').first().json;
const config = $('Read cursor and form config').first().json;
return responses.map(response => {
  const rawTime = response.lastSubmittedTime || response.createTime;
  const milliseconds = Date.parse(rawTime || '');
  if (!response.responseId || !Number.isFinite(milliseconds)) throw new Error('Form response is missing a stable responseId or valid timestamp.');
  return { json: { form_id: config.form_id, form, response, response_time_ms: milliseconds, run_mode: config.run_mode } };
});

const results = $input.all().map(item => item.json);
const sourceEvents = $('Prepare response events').all().map(item => item.json);
if (results.length !== sourceEvents.length) throw new Error('Not every fetched response has a workflow result; cursor remains unchanged.');
for (const result of results) {
  const state = result?.steps?.store?.business_result?.state;
  if (!['STORED', 'DUPLICATE', 'PREVIEWED'].includes(state)) throw new Error('At least one response did not reach an accepted storage state; cursor remains unchanged.');
}
const mode = $('Read cursor and form config').first().json.run_mode;
if (mode !== 'MOCK' && mode !== 'REAL') return [{ json: { cursor_advanced: false, reason: 'DRY_RUN does not consume source responses' } }];
const maxMilliseconds = Math.max(...sourceEvents.map(event => event.response_time_ms));
const state = $getWorkflowStaticData('global');
const previous = Date.parse(state.lastSubmittedTime || '') || 0;
state.lastSubmittedTime = new Date(Math.max(previous, maxMilliseconds)).toISOString();
return [{ json: { cursor_advanced: true, last_submitted_time: state.lastSubmittedTime, processed: results.length } }];
